				{
					loadTemplateIcon = new Texture2D(512, 512, TextureFormat.ARGB32, mipChain: false);
					loadTemplateIcon.LoadImage(loadTemplateIconBytes);
					loadTemplateIcon.Apply();
				}
				return loadTemplateIcon;
			}
		}

